// @ts-check

// Module-scoped state shared by every `NamespaceCache` instance so the
// singleton pattern below always operates on a single source of truth,
// mirroring the locked pattern used by the Python `NamespaceCache`. Node.js
// is single-threaded, so a real mutex isn't needed here: every method on
// this class is fully synchronous (no `await`/Promise boundaries), which
// means the JS event loop can never interleave two mutations of
// `_namespaceCache`. If an async method is ever added, guard its critical
// section with an explicit lock instead of relying on this invariant.
/** @type {string[]} */
const _namespaceCache = []

/** @type {NamespaceCache | null} */
let _instance = null

class NamespaceCache {
    constructor() {
        if (_instance === null) {
            _instance = this
        }
        return _instance
    }

    /**
     * @param {string} namespaceRegex
     */
    cacheNamespace(namespaceRegex) {
        _namespaceCache.push(namespaceRegex)
    }

    /**
     * @returns {boolean}
     */
    isNamespaceCacheEmpty() {
        return _namespaceCache.length === 0
    }

    /**
     * @param {string} typeToCheck
     * @returns {boolean}
     */
    isTypeAllowed(typeToCheck) {
        for (let pattern of _namespaceCache) {
            if (new RegExp(pattern).test(typeToCheck.constructor.name)) {
                return true
            }
        }
        return false
    }

    getCachedNamespaces() {
        return _namespaceCache.slice()
    }

    clearCache() {
        _namespaceCache.length = 0
        return 0
    }
}

export { NamespaceCache }
